  "HDC Uniform tuyển chọn hơn 10+ dòng vải chuyên dụng cao cấp từ tự nhiên và công nghệ mới. 100% dòng vải đều qua kiểm định an toàn, kháng khuẩn, chống xù lông và giữ phom dáng bền đẹp suốt hàng năm sử dụng.": {
    en: "HDC Uniform selects over 10+ premium specialized fabrics from natural and new technologies. 100% of the fabrics pass safety, antibacterial, anti-pilling inspections, and maintain a durable, beautiful shape throughout years of use.",
    ko: "HDC Uniform은 천연 및 신기술이 적용된 10여 가지 이상의 고급 특수 원단을 엄선합니다. 모든 원단은 안전, 항균, 보풀 방지 테스트를 통과했으며 다년간 사용해도 형태가 잘 유지됩니다.",
    ja: "HDC Uniformは、天然素材および新技術による10種類以上の高級専用生地を厳選しています。すべての生地は安全性、抗菌性、抗ピリング性の検査をクリアしており、長期間使用しても美しい形状を保ちます。",
    th: "HDC Uniform คัดสรรผ้าชนิดพิเศษระดับพรีเมียมมากกว่า 10 ชนิดจากธรรมชาติและเทคโนโลยีใหม่ ผ้า 100% ผ่านการทดสอบความปลอดภัย ต้านเชื้อแบคทีเรีย ป้องกันขุย และรักษารูปทรงที่สวยงามทนทานตลอดอายุการใช้งาน",
    zh: "HDC Uniform 精选 10 多种来自天然和新技术的优质专用面料。 100% 的面料均通过安全、抗菌、抗起球检测，并在多年的使用中保持耐用、美观的形状。",
    us: "HDC Uniform selects over 10+ premium specialized fabrics from natural and new technologies. 100% of the fabrics pass safety, antibacterial, anti-pilling inspections, and maintain a durable, beautiful shape throughout years of use.",
    fr: "HDC Uniform sélectionne plus de 10 tissus spécialisés haut de gamme issus de technologies naturelles et nouvelles. 100 % des tissus passent les inspections de sécurité, antibactériennes et anti-boulochage, et conservent une forme durable et belle tout au long des années d'utilisation.",
    de: "HDC Uniform wählt über 10+ erstklassige Spezialstoffe aus natürlichen und neuen Technologien aus. 100 % der Stoffe bestehen Sicherheits-, antibakterielle und Anti-Pilling-Prüfungen und behalten über Jahre der Nutzung eine dauerhafte, schöne Form.",
    sg: "HDC Uniform selects over 10+ premium specialized fabrics from natural and new technologies. 100% of the fabrics pass safety, antibacterial, anti-pilling inspections, and maintain a durable, beautiful shape throughout years of use."
  },
