      "ja": "名だたる企業クライアントに最も選ばれている、主要5カテゴリーを代表するシグネチャーモデル。",
      "ko": "수많은 기업 고객이 가장 많이 선택한 5대 핵심 라인업의 대표 유니폼 모델입니다.",
      "zh": "历经千家集团企业实地甄选、广受好评的5大主流标杆制服款式。",
      "fr": "Les uniformes les plus plébiscités par nos entreprises clientes, représentant nos 5 lignes phares.",
      "de": "Die beliebtesten Unternehmensuniformen unserer Kunden — stellvertretend für 5 Hauptlinien.",
      "th": "ชุดยูนิฟอร์มที่องค์กรธุรกิจเลือกใช้มากที่สุด ตัวแทนของ 5 ผลิตภัณฑ์หลัก",
