const REVERSE_LOOKUP = new Map();
const PHRASE_LIST = [];

for (const [key, val] of Object.entries(TRANSLATIONS)) {
  if (!val) continue;
  if (val.vi && typeof val.vi === "string") {
    const viTrim = val.vi.trim();
    const viNorm = viTrim.toLowerCase();
    if (viTrim && !REVERSE_LOOKUP.has(viNorm)) {
      REVERSE_LOOKUP.set(viNorm, val);
      if (viTrim.length >= 3) {
        PHRASE_LIST.push({ vi: viTrim, val });
      }
    }
  }
  if (!key.includes(".")) {
    const keyTrim = key.trim();
    const keyNorm = keyTrim.toLowerCase();
    if (keyTrim && !REVERSE_LOOKUP.has(keyNorm)) {
      REVERSE_LOOKUP.set(keyNorm, val);
      if (keyTrim.length >= 3) {
        PHRASE_LIST.push({ vi: keyTrim, val });
      }
    }
  }
}

// Sắp xếp các cụm từ theo chiều dài giảm dần (cụm dài ưu tiên dịch trước)
PHRASE_LIST.sort((a, b) => b.vi.length - a.vi.length);

export function translateSingleString(str, lang) {
  if (!str || typeof str !== "string" || lang === "vi") return str;
  const trimmed = str.trim();
  if (!trimmed) return str;
  const norm = trimmed.toLowerCase();

  // 1. Khớp chính xác 100% trong từ điển (O(1) siêu tốc)
  const direct = REVERSE_LOOKUP.get(norm);
  if (direct) {
    const res = direct[lang] || direct["en"] || direct["vi"];
    if (res) {
      const leading = str.match(/^\s*/)?.[0] || "";
      const trailing = str.match(/\s*$/)?.[0] || "";
      const isUpper = trimmed === trimmed.toUpperCase() && trimmed.length > 2;
      return leading + (isUpper ? res.toUpperCase() : res) + trailing;
    }
  }

  // 2. Khớp cụm từ trong câu dài / đoạn văn
  if (trimmed.length >= 6) {
    let replaced = str;
    let modified = false;
    for (let i = 0; i < PHRASE_LIST.length; i++) {
      const p = PHRASE_LIST[i];
      if (p.vi.length >= 4 && replaced.includes(p.vi)) {
        const target = p.val[lang] || p.val["en"] || p.val["vi"];
        if (target && target !== p.vi) {
          replaced = replaced.replaceAll(p.vi, target);
          modified = true;
        }
      }
    }
    if (modified) return replaced;
  }

  return str;
}

const IGNORED_TAGS = new Set(["SCRIPT", "STYLE", "SVG", "CODE", "PRE", "TEXTAREA"]);

function translateDomTree(root, lang) {
  if (!root || typeof window === "undefined" || lang === "vi") return;

  const walker = document.createTreeWalker(
    root,
    NodeFilter.SHOW_TEXT | NodeFilter.SHOW_ELEMENT,
    {
      acceptNode(n) {
        if (n.nodeType === Node.ELEMENT_NODE) {
          if (IGNORED_TAGS.has(n.tagName)) return NodeFilter.FILTER_REJECT;
          if (n.classList && (n.classList.contains("notranslate") || n.closest(".notranslate"))) {
            return NodeFilter.FILTER_REJECT;
          }
          return NodeFilter.FILTER_ACCEPT;
        }
        if (n.nodeType === Node.TEXT_NODE) {
          const parent = n.parentElement;
          if (parent) {
            if (IGNORED_TAGS.has(parent.tagName)) return NodeFilter.FILTER_REJECT;
            if (parent.closest(".notranslate")) return NodeFilter.FILTER_REJECT;
          }
          return NodeFilter.FILTER_ACCEPT;
        }
        return NodeFilter.FILTER_SKIP;
      }
    }
  );

  let node;
  while ((node = walker.nextNode())) {
    if (node.nodeType === Node.TEXT_NODE) {
      if (node.__hdc_orig === undefined) {
        node.__hdc_orig = node.nodeValue;
      }
      const orig = node.__hdc_orig;
      if (orig && orig.trim()) {
        const translated = translateSingleString(orig, lang);
        if (node.nodeValue !== translated) {
          node.nodeValue = translated;
        }
      }
    } else if (node.nodeType === Node.ELEMENT_NODE) {
      if (node.tagName === "INPUT" && node.placeholder) {
        if (node.__hdc_orig_ph === undefined) {
          node.__hdc_orig_ph = node.placeholder;
        }
        const phTrans = translateSingleString(node.__hdc_orig_ph, lang);
        if (node.placeholder !== phTrans) {
          node.placeholder = phTrans;
        }
      }
      if (node.title) {
        if (node.__hdc_orig_title === undefined) {
          node.__hdc_orig_title = node.title;
        }
        const titleTrans = translateSingleString(node.__hdc_orig_title, lang);
        if (node.title !== titleTrans) {
          node.title = titleTrans;
        }
      }
    }
  }
}

function restoreDomTree(root) {
  if (!root || typeof window === "undefined") return;

  const walker = document.createTreeWalker(
    root,
    NodeFilter.SHOW_TEXT | NodeFilter.SHOW_ELEMENT,
    null
  );

  let node;
  while ((node = walker.nextNode())) {
    if (node.nodeType === Node.TEXT_NODE) {
      if (node.__hdc_orig !== undefined && node.nodeValue !== node.__hdc_orig) {
        node.nodeValue = node.__hdc_orig;
      }
    } else if (node.nodeType === Node.ELEMENT_NODE) {
      if (node.__hdc_orig_ph !== undefined && node.placeholder !== node.__hdc_orig_ph) {
        node.placeholder = node.__hdc_orig_ph;
      }
      if (node.__hdc_orig_title !== undefined && node.title !== node.__hdc_orig_title) {
        node.title = node.__hdc_orig_title;
      }
    }
  }
}

// CONTEXT CREATION (100% NATIVE REACT STATE — KHÔNG DÙNG GOOGLE TRANSLATE)
// ============================================================
const LanguageContext = createContext({
  language: "vi",
  setLanguage: () => {},
  t: (key, fallback) => fallback || key,
  currentLang: SUPPORTED_LANGUAGES[0],
  supportedLanguages: SUPPORTED_LANGUAGES,
});

export const GOOGLE_LANG_MAP = {
  vi: "vi",
  en: "en",
  us: "en",
  sg: "en",
  ja: "ja",
  ko: "ko",
  zh: "zh-CN",
  fr: "fr",
  de: "de",
  th: "th",
};

function setGoogleTransCookie(targetLang) {
  if (typeof document === "undefined") return;
  const hostname = window.location.hostname;
  if (!targetLang || targetLang === "vi") {
    document.cookie = "googtrans=; expires=Thu, 01 Jan 1970 00:00:00 UTC; path=/;";
    document.cookie = `googtrans=; expires=Thu, 01 Jan 1970 00:00:00 UTC; path=/; domain=${hostname};`;
    document.cookie = `googtrans=; expires=Thu, 01 Jan 1970 00:00:00 UTC; path=/; domain=.${hostname};`;
  } else {
    const gLang = GOOGLE_LANG_MAP[targetLang] || "en";
    const val = `/vi/${gLang}`;
    document.cookie = `googtrans=${val}; path=/;`;
    if (hostname && hostname !== "localhost") {
      document.cookie = `googtrans=${val}; path=/; domain=${hostname};`;
      document.cookie = `googtrans=${val}; path=/; domain=.${hostname};`;
    }
  }
}

export function LanguageProvider({ children, initialLanguage = "vi" }) {
  const [language, setLanguageState] = useState(initialLanguage);
  const pathname = usePathname();

  // 1. Tải ngôn ngữ đã lưu & khởi tạo Google Translate ngầm
  useEffect(() => {
    if (typeof window === "undefined") return;

    try {
      const saved = localStorage.getItem("hdc_lang");
      if (saved && SUPPORTED_LANGUAGES.some((l) => l.code === saved)) {
        setLanguageState(saved);
        document.documentElement.lang = saved;
        if (saved !== "vi") {
          setGoogleTransCookie(saved);
        }
      }
    } catch (_) {}

    // Callback khởi tạo Google Translate Element
    window.googleTranslateElementInit = function () {
      try {
        if (window.google && window.google.translate) {
          new window.google.translate.TranslateElement(
            {
              pageLanguage: "vi",
              includedLanguages: "vi,en,ja,ko,zh-CN,fr,de,th",
              autoDisplay: false,
            },
            "google_translate_element"
          );
        }
      } catch (err) {
        // silent
      }
    };

    // Tải Google Translate script nếu chưa có
    if (!document.getElementById("google-translate-script")) {
      const script = document.createElement("script");
      script.id = "google-translate-script";
      script.src = "https://translate.google.com/translate_a/element.js?cb=googleTranslateElementInit";
      script.async = true;
      document.body.appendChild(script);
    }
  }, []);

  // 2. Tự động đồng bộ và kích hoạt dịch trên mọi trang khi chuyển route
  useEffect(() => {
    if (typeof window === "undefined" || typeof document === "undefined") return;

    if (language === "vi") {
      restoreDomTree(document.body);
      return;
    }

    // Dịch tức thì các cụm từ trong từ điển (0ms)
    translateDomTree(document.body, language);

    // Kích hoạt Google Translate xử lý toàn bộ các đoạn văn bản còn lại của trang
    const gLang = GOOGLE_LANG_MAP[language] || "en";
    const triggerTranslation = () => {
      const combo = document.querySelector(".goog-te-combo");
      if (combo) {
        if (combo.value !== gLang) {
          combo.value = gLang;
        }
        combo.dispatchEvent(new Event("change"));
      }
    };

    const t1 = setTimeout(triggerTranslation, 100);
    const t2 = setTimeout(triggerTranslation, 350);

    return () => {
      clearTimeout(t1);
      clearTimeout(t2);
    };
  }, [language, pathname]);

  // 3. Hàm chuyển đổi ngôn ngữ toàn diện (luôn reload trang để đồng bộ SSR và Client)
  const setLanguage = (newLang) => {
    setLanguageState(newLang);
    try {
      localStorage.setItem("hdc_lang", newLang);
      if (typeof document !== "undefined") {
        document.documentElement.lang = newLang;
        document.cookie = `hdc_lang=${newLang}; path=/; max-age=31536000;`;
        setGoogleTransCookie(newLang);
        // Luôn reload để SSR đồng bộ và nạp lại toàn bộ trang với ngôn ngữ mới
        window.location.reload();
      }
    } catch (_) {
      if (typeof window !== "undefined") {
        window.location.reload();
      }
    }
  };

  const currentLang =
    SUPPORTED_LANGUAGES.find((l) => l.code === language) ||
    SUPPORTED_LANGUAGES[0];

  const t = (key, fallback = "") => {
    if (!key) return fallback || "";
    const entry = TRANSLATIONS[key] || REVERSE_LOOKUP.get(key.trim().toLowerCase());
    if (!entry) return fallback || key;
    return entry[language] || entry["en"] || entry["vi"] || fallback || key;
  };

  return (
    <LanguageContext.Provider
      value={{
        language,
        setLanguage,
        t,
        currentLang,
        supportedLanguages: SUPPORTED_LANGUAGES,
      }}
    >
      {/* Container ẩn cho Google Translate Engine */}
      <div id="google_translate_element" style={{ display: "none" }} aria-hidden="true" />
      {children}
    </LanguageContext.Provider>
  );
}

export function useLanguage() {
  const ctx = useContext(LanguageContext);
  if (!ctx) {
    return {
      language: "vi",
      setLanguage: () => {},
      t: (key, fallback) => fallback || key,
      currentLang: SUPPORTED_LANGUAGES[0],
      supportedLanguages: SUPPORTED_LANGUAGES,
      changeLanguage: () => {},
    };
  }
  return ctx;
}

